bool ReadDialogTemplate(std::uint32_t id, KauaiDialogs::Resource &resource) {
    switch (id) {
    case 211: return KauaiDialogs::ReadResource(dialog211, sizeof(dialog211), resource);
    case 212: return KauaiDialogs::ReadResource(dialog212, sizeof(dialog212), resource);
    case 213: return KauaiDialogs::ReadResource(dialog213, sizeof(dialog213), resource);
    case 214: return KauaiDialogs::ReadResource(dialog214, sizeof(dialog214), resource);
    case 215: return KauaiDialogs::ReadResource(dialog215, sizeof(dialog215), resource);
    case 216: return KauaiDialogs::ReadResource(dialog216, sizeof(dialog216), resource);
    case 218: return KauaiDialogs::ReadResource(dialog218, sizeof(dialog218), resource);
    case 219: return KauaiDialogs::ReadResource(dialog219, sizeof(dialog219), resource);
    case 220: return KauaiDialogs::ReadResource(dialog220, sizeof(dialog220), resource);
    case 221: return KauaiDialogs::ReadResource(dialog221, sizeof(dialog221), resource);
    case 222: return KauaiDialogs::ReadResource(dialog222, sizeof(dialog222), resource);
    case 223: return KauaiDialogs::ReadResource(dialog223, sizeof(dialog223), resource);
    case 224: return KauaiDialogs::ReadResource(dialog224, sizeof(dialog224), resource);
    case 226: return KauaiDialogs::ReadResource(dialog226, sizeof(dialog226), resource);
    case 227: return KauaiDialogs::ReadResource(dialog227, sizeof(dialog227), resource);
    default: return false;
    }
}
bool ReadDialog(std::uint32_t id, KauaiDialogs::Resource &resource) {
    if (!ReadDialogTemplate(id, resource)) return false;
#ifndef DEBUG
    // The bundle comes from the Debug RC build. Match Release item
    // numbering by removing Product Info's developer-only readout.
    if (id == 218) {
        for (auto item = resource.controls.begin(); item != resource.controls.end();) {
            if (item->id == 1025 || item->title.text == u"cactAV:")
                item = resource.controls.erase(item);
            else ++item;
        }
    }
#endif
    return true;
}
struct RegisterDialogs { RegisterDialogs() { KauaiDialogs::SetResourceProvider(ReadDialog); } } registerDialogs;
